public static int lastAndRemove(Stack<Integer> s) {
    Stack<Integer> temp = new Stack<Integer>();
    while (!s.isEmpty()) {
        temp.push(s.pop());
    }
    int last = temp.pop();   // האיבר שהיה בתחתית
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return last;
}

public static Stack<TwoItems> stackTwoItems(Stack<Integer> stk1) {
    Stack<TwoItems> result = new Stack<TwoItems>();
    while (!stk1.isEmpty()) {
        int top = stk1.pop();
        int bottom = lastAndRemove(stk1);
        result.push(new TwoItems(top, bottom));
    }
    return result;
}

