public static int LastAndRemove(Stack<int> s)
{
    Stack<int> temp = new Stack<int>();
    while (!s.IsEmpty())
    {
        temp.Push(s.Pop());
    }
    int last = temp.Pop();   // האיבר שהיה בתחתית
    while (!temp.IsEmpty())
    {
        s.Push(temp.Pop());
    }
    return last;
}

public static Stack<TwoItems> StackTwoItems(Stack<int> stk1)
{
    Stack<TwoItems> result = new Stack<TwoItems>();
    while (!stk1.IsEmpty())
    {
        int top = stk1.Pop();
        int bottom = LastAndRemove(stk1);
        result.Push(new TwoItems(top, bottom));
    }
    return result;
